UPDATE activity
title = #{title}, venue_id = #{venueId}, location = #{location}, start_time = #{startTime}, end_time = #{endTime}, max_players = #{maxPlayers}, current_players = #{currentPlayers}, level_require = #{levelRequire}, description = #{description}, status = #{status}, update_time = NOW()
WHERE aid = #{aid}
